int yarv_unicode_printable(uint32_t c, uint32_t version)
{
    uint32_t age;
    size_t low = 0;
    size_t high = YARV_PRINT_RANGES;

    if (c < 0x100) {
        /* Onigmo's ISO-8859-1 ctype table. */
        return (c >= 0x20 && c < 0x7F) || c == 0x85 || c >= 0xA0;
    }
    if (version >= YARV_MODE(4, 0)) {
        age = 3;
    } else if (version >= YARV_MODE(3, 2)) {
        age = 2;
    } else if (version >= YARV_MODE(3, 1)) {
        age = 1;
    } else {
        age = 0;
    }
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if ((yarv_print_ranges[middle][0] & 0xFFFFFFu) <= c) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if (low == 0) {
        return 0;
    }
    --low;
    return c <= yarv_print_ranges[low][1] && (yarv_print_ranges[low][0] >> 24) <= age;
}

